-- Shared, public syllabus catalogue. Student edits live in subject_topics and
-- subject_assessments; these rows are immutable templates for new copies.
CREATE TABLE syllabus_catalog (
  id TEXT PRIMARY KEY,
  country_code TEXT NOT NULL,
  state_code TEXT,
  authority TEXT NOT NULL,
  subject TEXT NOT NULL,
  version_identifier TEXT NOT NULL,
  year_levels TEXT NOT NULL,
  source_title TEXT NOT NULL,
  source_url TEXT,
  source_license TEXT,
  source_attribution TEXT,
  document_sha256 TEXT UNIQUE,
  topics_json TEXT NOT NULL,
  assessments_json TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE INDEX syllabus_catalog_lookup ON syllabus_catalog(country_code, state_code, subject);

