INSERT INTO syllabus_catalog VALUES ('992cb8e9-1417-52ca-af5c-b9845ee357e6','AU','QLD','Queensland Curriculum and Assessment Authority','English','2025 v1.3','["11", "12"]','English 2025 v1.3 General senior syllabus','https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_english_25_syll.pdf','Creative Commons Attribution 4.0 International','© State of Queensland (QCAA) 2026 www.qcaa.qld.edu.au/copyright',NULL,'[{"title":"Unit 1 Perspectives and texts","detail":"Analyse and create representations and perspectives for varied purposes, contexts and audiences.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed pages 17–20, Unit 1"},{"title":"Unit 2 Texts and culture","detail":"Explore how language, identity and cultural contexts shape texts, meanings and audience positions.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed pages 21–23, Unit 2"},{"title":"3.1 Conversations about issues in texts","detail":"Compare representations of an issue and create persuasive arguments for public audiences.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed pages 25–26, Unit 3 Topic 1"},{"title":"3.2 Conversations about concepts in texts","detail":"Compare how texts construct a shared concept and create analytical responses about textual connections.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed pages 27–28, Unit 3 Topic 2"},{"title":"4.1 Creative responses to literary texts","detail":"Experiment with language, style and textual elements to create imaginative responses to literary texts.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 30, Unit 4 Topic 1"},{"title":"4.2 Critical responses to literary texts","detai