INSERT INTO syllabus_catalog VALUES ('84dfb812-403d-53ba-a2c8-13d395849016','AU','QLD','Queensland Curriculum and Assessment Authority','General Mathematics','2025 v1.3','["11", "12"]','General Mathematics 2025 v1.3 General senior syllabus','https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_general_25_syll.pdf','Creative Commons Attribution 4.0 International','© State of Queensland (QCAA) 2026 www.qcaa.qld.edu.au/copyright',NULL,'[{"title":"1.1 Consumer arithmetic","detail":"Calculate wages, prices, percentages, simple interest, budgets and financial comparisons.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 15, Unit 1 Topic 1"},{"title":"1.2 Shape and measurement","detail":"Apply measurement, perimeter, area, volume, capacity and error concepts to practical contexts.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed pages 15–16, Unit 1 Topic 2"},{"title":"1.3 Similarity and scale","detail":"Use similarity, scale factors, plans and maps to solve measurement problems.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 17, Unit 1 Topic 3"},{"title":"1.4 Algebra","detail":"Simplify and evaluate algebraic expressions, formulas and equations in practical situations.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 17, Unit 1 Topic 4"},{"title":"1.5 Linear equations and their graphs","detail":"Solve linear equations and interpret gradients, intercepts and graphs of linear relationships.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 17, Unit 1 Topic 5"},{"title":"2.1 Applications of linear equations and graphs","detail":"Model practical situations with linear equations, simultaneous equations and piecewise graphs.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 19, Unit 2 Topic 1"},{"title":"2.2 Applications of trigonometry","detail":"Use right-triangle trigonometry, bearings, elevation and depression in practical problems.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 19, Unit 2 Topic 2"},{"title":"2.3 Matrices","detail":"Perform matrix operations and use matrices to represent data, transitions and practical systems.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 20, Unit 2 Topic 3"},{"title":"2.4 Univariate data analysis 1","detail":"Organise and display univariate data and calculate measures of centre and spread.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 20, Unit 2 Topic 4"},{"title":"2.5 Univariate data analysis 2","detail":"Interpret distributions, boxplots, standard deviation, outliers and comparisons between datasets.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 21, Unit 2 Topic 5"},{"title":"3.1 Bivariate data analysis 1","detail":"Construct and interpret two-way tables and scatterplots and identify associations between variables.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 23, Unit 3 Topic 1"},{"title":"3.2 Bivariate data analysis 2","detail":"Use correlation and least-squares lines to model and interpret bivariate relationships.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 23, Unit 3 Topic 2"},{"title":"3.3 Time series analysis","detail":"Graph, smooth and interp