INSERT INTO syllabus_catalog VALUES ('b8eecc84-c841-5af3-bf10-c6ab1738cc29','AU','QLD','Queensland Curriculum and Assessment Authority','Physics','2025 v1.3','["11", "12"]','Physics 2025 v1.3 General senior syllabus','https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_physics_25_syll.pdf','Creative Commons Attribution 4.0 International','© State of Queensland (QCAA) 2026 www.qcaa.qld.edu.au/copyright',NULL,'[{"title":"1.1 Heating processes","detail":"Study thermal equilibrium, specific heat, phase changes, energy transfer and thermodynamic processes.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 20, Unit 1 Topic 1"},{"title":"1.2 Ionising radiation and nuclear reactions","detail":"Examine nuclear structure, decay, radiation, half-life, fission, fusion and radiation safety.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed pages 21–22, Unit 1 Topic 2"},{"title":"1.3 Electrical circuits","detail":"Analyse charge, current, voltage, resistance, power and series and parallel circuits.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed pages 23–24, Unit 1 Topic 3"},{"title":"2.1 Linear motion and force","detail":"Model kinematics, forces, momentum, energy and collisions in one and two dimensions.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed pages 26–27, Unit 2 Topic 1"},{"title":"2.2 Waves","detail":"Study wave properties, sound, light, interference, diffraction, resonance and the electromagnetic spectrum.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed pages 28–29, Unit 2 Topic 2"},{"title":"3.1 Gravity and motion","detail":"Analyse gravitational fields, projectile and circular motion, satellites and orbital mechanics.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed pages 31–32, Unit 3 Topic 1"},{"title":"3.2 Electromagnetism","detail":"Study electric and magnetic fields, forces, induction, motors, generators and transformers.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed pages 33–34, Unit 3 Topic 2"},{"title":"4.1 Special relativity","detail":"Apply reference frames, time dilation, length contraction, simultaneity and mass-energy equivalence.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed pages 36–37, Unit 4 Topic 1"},{"title":"4.2 Quantum theory","detail":"Examine photons, wave-particle duality, atomic spectra and foundational quantum phenomena.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 38, Unit 4 Topic 2"},{"title":"4.3 The Standard Model","detail":"Study fundamental particles, interactions, conservation laws and evidence supporting the Standard Model.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 39, Unit 4 Topic 3"}]','[{"title":"IA1 Data test","kind":"test","dueOn":null,"dueLabel":"","dueTerm":null,"dueWeek":null,"weight":"10%","sourceReference":"Printed pages 40–42, Internal assessment 1"},{"title":"IA2 Student experiment","kind":"prac","dueOn":null,"dueLabel":"","dueTerm":null,"dueWeek":null,"weight":"20%","sourceReference":"Printed pages 43–46, Internal assessment 2"},{"title":"IA3 Research investigation","kind":"assignment","dueOn":null,"dueLabel":"","dueTerm":null,"dueWeek":null,"weight":"20%","sourceReference":"Printed pages 47–50, Internal assessment 3"},{"title":"External assessment: Examination — combination response","kind":"exam","dueOn":null,"dueLabe