INSERT INTO syllabus_catalog VALUES ('d5cc2f4e-fb5a-5322-be9c-0bf73868e9d5','AU','QLD','Queensland Curriculum and Assessment Authority','Specialist Mathematics','2025 v1.4','["11", "12"]','Specialist Mathematics 2025 v1.4 General senior syllabus','https://www.qcaa.qld.edu.au/downloads/senior-qce/syllabuses/snr_maths_specialist_25_syll.pdf','Creative Commons Attribution 4.0 International','© State of Queensland (QCAA) 2026 www.qcaa.qld.edu.au/copyright',NULL,'[{"title":"1.1 Combinatorics","detail":"Use permutations, combinations, counting principles and the inclusion-exclusion principle.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 16, Unit 1 Topic 1"},{"title":"1.2 Introduction to proof","detail":"Use implication, equivalence, direct proof, contradiction and counterexamples.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 17, Unit 1 Topic 2"},{"title":"1.3 Vectors in the plane","detail":"Represent, operate with and interpret two-dimensional vectors geometrically and algebraically.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 17, Unit 1 Topic 3"},{"title":"1.4 Algebra of vectors in two dimensions","detail":"Use vector components, scalar products, projections and geometric applications in the plane.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 18, Unit 1 Topic 4"},{"title":"1.5 Matrices","detail":"Perform matrix operations and use inverses, determinants and systems of linear equations.","startsOn":null,"endsOn":null,"startTerm":null,"startWeek":null,"endTerm":null,"endWeek":null,"sourceReference":"Printed page 19, Unit 1 Topic 5"},{"title":"2.1 Complex numbers","detail":"Represent complex numbers in Cartesian form and use the complex plane, modulus 